"""One folder per run: settings.json, curve.csv, checkpoints, games.npz, status (AD-06)."""

import csv
import dataclasses
import json
import zipfile
from collections.abc import Mapping, Sequence
from datetime import datetime
from pathlib import Path
from typing import Any, Literal, cast

import numpy as np

from rllab.core import SOLO, Agent, AgentParams, Exploration, Rewards, RunSettings
from rllab.runs.types import CurvePoint, GameRecording, RunRecord

Status = Literal["running", "complete", "incomplete"]

_SETTINGS = "settings.json"
_CURVE = "curve.csv"
_GAMES = "games.npz"
_STATUS = "status"
_GENERATIONS = "generations"
_CURVE_FIELDS = [f.name for f in dataclasses.fields(CurvePoint)]
_STATUSES = ("running", "complete", "incomplete")
_BOARDS = ("grid", "tank")


class RunWriter:
    """Writes one run folder as the run goes; each curve point is flushed at once."""

    def __init__(self, path: Path, settings: RunSettings) -> None:
        self._path = path
        self._suffix = ".npz" if settings.agent == "tabular" else ".pt"

    def add_point(self, p: CurvePoint) -> None:
        with (self._path / _CURVE).open("a", newline="", encoding="utf-8") as f:
            csv.writer(f).writerow([getattr(p, name) for name in _CURVE_FIELDS])

    def save_checkpoint(self, agent: Agent, *, team: str = SOLO) -> None:
        stem = "checkpoint" if team == SOLO else f"checkpoint-{team}"
        agent.save(self._path / f"{stem}{self._suffix}")

    def save_generation(self, agent: Agent, *, team: str, index: int) -> Path:
        path = self._path / _GENERATIONS / team / str(index)
        path.parent.mkdir(parents=True, exist_ok=True)
        agent.save(path)
        return path

    def save_games(self, games: Sequence[GameRecording]) -> None:
        arrays: dict[str, np.ndarray] = {}
        for i, game in enumerate(games):
            arrays[f"{i}.seed"] = np.asarray(game.seed)
            arrays[f"{i}.board"] = np.asarray(game.board)
            arrays[f"{i}.frames"] = game.frames
            arrays[f"{i}.rewards"] = game.rewards
            for team, scores in game.scores.items():
                arrays[f"{i}.scores.{team}"] = scores
        np.savez_compressed(self._path / _GAMES, allow_pickle=False, **arrays)

    def finish(self, status: Literal["complete", "incomplete"]) -> RunRecord:
        (self._path / _STATUS).write_text(status, encoding="utf-8")
        return open_run(self._path)


def create_run(settings: RunSettings, *, root: Path = Path("runs")) -> RunWriter:
    """Start a uniquely named run folder holding settings.json and status=running."""
    path = _new_folder(root, f"{settings.name}-s{settings.seed}-{datetime.now():%Y%m%d-%H%M%S}")
    (path / _SETTINGS).write_text(json.dumps(_settings_json(settings), indent=1), encoding="utf-8")
    with (path / _CURVE).open("w", newline="", encoding="utf-8") as f:
        csv.writer(f).writerow(_CURVE_FIELDS)
    (path / _STATUS).write_text("running", encoding="utf-8")
    return RunWriter(path, settings)


def open_run(path: Path) -> RunRecord:
    """Read a run folder back; FileNotFoundError naming the run if it has no settings.json."""
    if not (path / _SETTINGS).is_file():
        raise FileNotFoundError(f"run {path}: no {_SETTINGS}")
    settings = _read_settings(path / _SETTINGS)
    return RunRecord(
        path=path,
        settings=settings,
        curve=_read_curve(path / _CURVE),
        status=_read_status(path / _STATUS),
        checkpoints=_find_checkpoints(path),
        generations=_find_generations(path / _GENERATIONS),
        games=_read_games(path / _GAMES),
    )


def _new_folder(root: Path, base: str) -> Path:
    root.mkdir(parents=True, exist_ok=True)
    n = 0
    while True:
        path = root / (base if n == 0 else f"{base}-{n}")
        try:
            path.mkdir()
        except FileExistsError:
            n += 1
            continue
        return path


def _settings_json(settings: RunSettings) -> dict[str, Any]:
    data = dataclasses.asdict(settings)
    data["opponents"] = dict(settings.opponents)
    return data


def _read_settings(path: Path) -> RunSettings:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return RunSettings(
            **{
                **data,
                "rewards": Rewards(**data["rewards"]),
                "exploration": Exploration(**data["exploration"]),
                "params": AgentParams(**data["params"]),
            }
        )
    except (json.JSONDecodeError, KeyError, TypeError) as e:
        raise ValueError(f"{path}: unreadable settings") from e


def _read_curve(path: Path) -> tuple[CurvePoint, ...]:
    if not path.is_file():
        return ()
    with path.open(newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
    try:
        return tuple(
            CurvePoint(
